import numpy as np, pandas as pd, xgboost as xgb
NUM=["trainspeed","hazmatcars","loadedfreightcars","emptyfreightcars","grosstonnage","temperature"]
CATS=["equipmenttype","tracktype","weathercondition","visibility","accidenttype","reporting_railroad_class","stateabbr"]
CFG=dict(cat_mode='native', drop=[], eng=False, tc_num=True, params=dict(n_estimators=100,max_depth=6,learning_rate=0.1), min_count=1)

def fit(X_train, y_train, *, seed, threads, cfg=None):
    cfg=dict(CFG) if cfg is None else cfg
    cats=[c for c in CATS if c not in cfg['drop']]
    levels={}
    for c in cats:
        vc=X_train[c].value_counts()
        levels[c]=sorted(vc[vc>=cfg['min_count']].index)
    state={'cfg':cfg,'levels':levels}
    if cfg['cat_mode']=='te':
        # smoothed training rate per level (used on scoring rows); training rows use K-fold OOF
        m=cfg.get('te_m',50); prior=y_train.mean(); te={}
        for c in cats:
            g=pd.DataFrame({'c':X_train[c].to_numpy(),'y':y_train}).groupby('c').y.agg(['sum','count'])
            te[c]={k:(s+m*prior)/(n+m) for k,s,n in zip(g.index,g['sum'],g['count'])}
        state['te']=te; state['prior']=prior
    Z=prepare(state,X_train)
    if cfg['cat_mode']=='te':
        rng=np.random.RandomState(seed); fold=rng.randint(0,5,len(X_train))
        for c in cats:
            col=np.zeros(len(X_train)); xc=X_train[c].to_numpy()
            for f in range(5):
                tm=fold!=f; pr=y_train[tm].mean()
                g=pd.DataFrame({'c':xc[tm],'y':y_train[tm]}).groupby('c').y.agg(['sum','count'])
                mp={k:(s+m*pr)/(n+m) for k,s,n in zip(g.index,g['sum'],g['count'])}
                col[~tm]=[mp.get(v,pr) for v in xc[~tm]]
            Z[c]=col
    w=None
    if cfg.get('recency'):
        r=np.arange(len(X_train))/max(1,len(X_train)-1); w=np.exp(cfg['recency']*(r-1))
    mono=cfg.get('mono')
    kw={}
    if mono: kw['monotone_constraints']={c:v for c,v in mono.items() if c in Z.columns}
    model=xgb.XGBClassifier(tree_method='hist',enable_categorical=True,random_state=seed,n_jobs=threads,**cfg['params'],**kw)
    model.fit(Z,y_train,sample_weight=w)
    state['model']=model
    return state

def prepare(state, X):
    cfg=state['cfg']; out={}
    sp=X['trainspeed'].to_numpy(dtype=float); hz=X['hazmatcars'].to_numpy(dtype=float)
    ld=X['loadedfreightcars'].to_numpy(dtype=float); em=X['emptyfreightcars'].to_numpy(dtype=float)
    tn=X['grosstonnage'].to_numpy(dtype=float); te=X['temperature'].to_numpy(dtype=float)
    te=np.where((te>130)|(te<-60),np.nan,te)
    base={'trainspeed':sp,'hazmatcars':hz,'loadedfreightcars':ld,'emptyfreightcars':em,'grosstonnage':tn,'temperature':te}
    for c in NUM:
        if c not in cfg['drop']: out[c]=base[c]
    if cfg['tc_num'] is not None and 'trackclass' not in cfg['drop']:
        tc=X['trackclass'].astype(object).to_numpy()
        tcn=np.array([np.nan if (v is None or v!=v) else (-1.0 if str(v).strip().upper()=='X' else _f(v)) for v in tc])
        out['trackclass']=tcn
    if cfg['eng']:
        E=cfg['eng'] if isinstance(cfg['eng'],(list,tuple,set)) else ALLENG
        cars=ld+em
        with np.errstate(divide='ignore',invalid='ignore'):
            ev={'cars':cars,
                'hz_frac':np.where(cars>0,hz/np.maximum(cars,1),np.nan),
                'hz_ld_frac':np.where(ld>0,hz/np.maximum(ld,1),np.nan),
                'ld_frac':np.where(cars>0,ld/np.maximum(cars,1),np.nan),
                'ton_car':np.where((cars>0)&(tn>0),tn/np.maximum(cars,1),np.nan),
                'ton0':(tn==0).astype(float),
                'ke':np.log1p(np.where(tn>0,tn,np.nan)*sp*sp),
                'mom':np.log1p(np.where(tn>0,tn,np.nan)*sp),
                'sp_hz':sp*hz,
                'sp2_cars':np.log1p(sp*sp*cars),
                'sp_hzfrac':sp*np.where(cars>0,hz/np.maximum(cars,1),np.nan),
                'hz_gt_ld':(hz>ld).astype(float),
                'hz_minus_ld':hz-ld,
                'exp_hz':np.log1p(sp)*np.log1p(hz),
               }
        for k in E: out[k]=ev[k]
    out=pd.DataFrame(out,index=X.index)
    mode=cfg['cat_mode']
    for c,lv in state['levels'].items():
        if mode=='native': out[c]=pd.Categorical(X[c],categories=lv)
        elif mode=='ord':
            mp={k:i for i,k in enumerate(lv)}; out[c]=[mp.get(v,np.nan) for v in X[c].to_numpy()]
        elif mode=='te':
            mp=state['te'][c]; out[c]=[mp.get(v,state['prior']) for v in X[c].to_numpy()]
        elif mode=='onehot':
            xc=X[c].to_numpy()
            for k in lv: out[c+'='+str(k)]=(xc==k).astype(float)
    return out
ALLENG=['cars','hz_frac','hz_ld_frac','ld_frac','ton_car','ton0','ke','mom','sp_hz','sp2_cars','sp_hzfrac','hz_gt_ld','hz_minus_ld','exp_hz']
def _f(v):
    try: return float(v)
    except Exception: return np.nan
